c=json.loads((D/'PROTOCOL.json').read_text());runs=json.loads((D/'summary.json').read_text());thresholds=np.round(np.arange(.20,.6001,.01),2).tolist();protocol=dict(stage='Exploratory post-result threshold sensitivity',thresholds=thresholds,sw2_threshold=.3,checkpoints=c['checkpoints'],fixed_configuration=dict(batch=16,h=.025,replicas=512,seeds=c['seeds']),cost='Unchanged setup-inclusive warm time',bootstrap_draws=c['bootstrap_draws'],bootstrap_seed=c['bootstrap_seed'],rule='Whole-seed paired bootstrap; earliest tested checkpoint passing joint aggregate accuracy. Keep Not Reached mass. No interpolation. Conditional speedup CI only on draws where both reach; point ratio unavailable if either point estimate never reaches.',limitations='Thresholds specified after accuracy outcomes were seen. Full sweep reported; no replacement of original threshold, no multiplicity-adjusted significance or global optimality claim.',source_hashes={str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [D/'PROTOCOL.json',D/'summary.json',D/'analysis.json']})
