 v=np.array([[[[z[t] for t in ['sw2','variance_nrmse']] for z in p['references']] for p in r['checkpoints']] for r in rs]);tm=np.array([[p['warm_total_seconds'] for p in r['checkpoints']] for r in rs]);V[m]=v.mean(0).max(1);B[m]=v[boot].mean(1).max(2);T[m]=tm.mean(0);TB[m]=tm[boot].mean(1)
