 both=(cross['cv1']>=0)&(cross['cv2']>=0);ratios=times['cv1'][both]/times['cv2'][both];point_reached=all(pts[m] is not None for m in c['methods']);row.update(point_speedup_cv1_over_cv2=float(row['cv1_seconds']/row['cv2_seconds']) if point_reached else None,conditional_speedup_ci95=ci(ratios) if both.any() else None,bootstrap_both_reached_fraction=float(both.mean()),status='both_reached' if point_reached else 'CV2_only_reached' if pts['cv2'] is not None else 'CV1_only_reached' if pts['cv1'] is not None else 'neither_reached',bootstrap_cv2_fewer_iterations_fraction_among_jointly_attained=float(np.mean(cross['cv2'][both]<cross['cv1'][both])) if both.any() else None);rows.append(row)
