 regions.append(dict(threshold_interval_closed_left_open_right=[lo,hi],cv1_K=ks['cv1'],cv2_K=ks['cv2'],point_speedup=ts['cv1']/ts['cv2'] if all(ts[m] is not None for m in c['methods']) else None))
